#!/usr/bin/env python3
# Paper Sec. 4: which DPS logarithms of the two-loop finite
# remainder are generated by UV renormalisation and by the Catani subtraction
# acting on the epsilon-expanded one-loop DPS term, and which must therefore
# sit in the unrenormalised two-loop amplitude itself.
#
# Inputs (no fitted numbers):
#  * the one-loop DPS region in dimensional regularisation. By dimensional
#    analysis its only p_T dependence at leading power is (p_T^2/mu^2)^(-eps)
#    times a function of eps:
#        spin 0:  (p_T^2/mu^2)^(-eps) [ -C_l/eps + a0 + a1 eps + a2 eps^2 ]
#        spin 2:  (p_T^2/mu^2)^(-eps) [  K       + k1 eps + k2 eps^2 ]
#    C_l is the coefficient of ln p_T^2 at one loop (C_1 = 2 C_l multiplies G),
#    K is the finite spin-two constant. a_i, k_i are scheme dependent and are
#    kept as symbols; the hard region is analytic in p_T and carries no log.
#  * UV renormalisation of the class-B amplitudes, Banerjee et al. Eq. (2.23):
#        M^(2)_R = M^(2)_B - (2 r_O + beta0)/eps M^(1)_B + (...) M^(0),  r_O = beta0,
#    i.e. -(3 beta0/eps) M^(1)_B. P1 App. B states the same structure for AA
#    (Z_GG^2 with Z_GG = Z_as, plus the coupling): dM^(2)/dln mu^2 = 3 beta0 M^(1).
#  * Catani subtraction, Banerjee et al. Eqs. (2.24), (2.25), P1 Eq. (2.14):
#        M^(2),fin = M^(2)_R - 2 I^(1) M^(1)_R - 4 I^(2) M^(0),
#        I^(1) = -e^(eps gamma)/Gamma(1-eps) (C_A/eps^2 + beta0/(2 eps)) (-mu^2/s)^eps .
#    I^(2) M^(0) and the M^(0) counterterms carry no p_T logarithm.
#
# Everything is done twice: in d = 4 - 2 eps (Catani, Banerjee et al.) and in
# d = 4 + eps (Bhattacharya et al., JHEP 02 (2020) 121, and P1), to show that the
# result does not depend on the convention. Logs: ell = ln(p_T^2/mu^2),
# Ls = ln(-s/mu^2); at leading power ell = 2 G + const, so only the highest powers
# and the beta0 parts are quoted as convention independent.
#
#   python3 stage2a_bookkeeping.py        (sympy; a few seconds)
import sympy as S

eps, ell, Ls, CA, b0, Cl, K = S.symbols('epsilon ell L_s C_A beta_0 C_l K')
a0, a1, a2, k1, k2 = S.symbols('a0 a1 a2 k1 k2')
G, c = S.symbols('G c')      # ell = 2 G + c at leading power; c collects constants and branch terms
gE = S.EulerGamma


def eps0(expr, e):
    # the O(e^0) term of a Laurent expansion in e (the poles are not needed here)
    return S.expand(S.series(expr, e, 0, 1).removeO()).coeff(e, 0)


def bookkeeping_d4m2e():
    region0 = S.exp(-eps*ell)*(-Cl/eps+a0+a1*eps+a2*eps**2)
    region2 = S.exp(-eps*ell)*(K+k1*eps+k2*eps**2)
    I1 = -S.exp(eps*gE)/S.gamma(1-eps)*(CA/eps**2+b0/(2*eps))*S.exp(-eps*Ls)
    uv = -3*b0/eps
    out = {}
    for name, region in (('spin0', region0), ('spin2', region2)):
        out[name] = S.expand(eps0((uv-2*I1)*region, eps))   # what UV + IR add to the remainder at O(eps^0)
    return out


def bookkeeping_d4pe():
    # same in d = 4 + e', e' = -2 eps: poles rescale, region (p_T^2/mu^2)^(e'/2) with 2 C_l/e'
    ep = S.symbols('epsilon_p')
    region0 = S.exp(ep*ell/2)*(2*Cl/ep+a0-a1*ep/2+a2*ep**2/4)
    region2 = S.exp(ep*ell/2)*(K-k1*ep/2+k2*ep**2/4)
    I1 = -S.exp(-ep*gE/2)/S.gamma(1+ep/2)*(4*CA/ep**2-b0/ep)*S.exp(ep*Ls/2)
    uv = 6*b0/ep
    out = {}
    for name, region in (('spin0', region0), ('spin2', region2)):
        out[name] = S.expand(eps0((uv-2*I1)*region, ep))
    return out


def in_G(expr):
    return S.expand(expr.subs(ell, 2*G+c))


if __name__ == '__main__':
    A = bookkeeping_d4m2e()
    B = bookkeeping_d4pe()
    for name in ('spin0', 'spin2'):
        diff = S.simplify(A[name]-B[name])
        print(f'{name}: d = 4-2eps and d = 4+eps give the same O(eps^0) terms:', diff == 0)
        assert diff == 0

    X0 = in_G(A['spin0'])
    X2 = in_G(A['spin2'])
    P0 = S.Poly(X0, G)
    P2 = S.Poly(X2, G)

    # spin zero: coefficients of G^3, and of beta0 G^2
    g3 = S.simplify(P0.coeff_monomial(G**3))
    g2 = S.expand(P0.coeff_monomial(G**2))
    g2_b0 = S.simplify(g2.coeff(b0))
    g2_rest = S.simplify(g2-g2_b0*b0)
    # spin two: G^2 and beta0 G
    h2 = S.simplify(P2.coeff_monomial(G**2))
    h1 = S.expand(P2.coeff_monomial(G))
    h1_b0 = S.simplify(h1.coeff(b0))
    h1_rest = S.simplify(h1-h1_b0*b0)

    # Express everything per unit of the one-loop coefficients: C_1 = 2 C_l multiplies G
    # in the spin-zero amplitude, K is the spin-two constant.
    C1 = S.symbols('C_1')
    unit = lambda e, u: S.simplify(e.subs(Cl, C1/2)/u)
    added = {'spin 0, C_1 G^3': unit(g3, C1), 'spin 0, C_1 beta0 G^2': unit(g2_b0, C1),
             'spin 2, K G^2': unit(h2, K), 'spin 2, K beta0 G': unit(h1_b0, K)}
    # measured finite remainder, same units (P1 Eqs. 4.14-4.17, Table 5; HH, paper Sec. 3;
    # the spin-two single log is P1's A21 = -(4/3) pi N_c (4N_c - n_f) = (4 C_A - 4 beta0) K)
    fin = {'spin 0, C_1 G^3': -S.Rational(4, 3)*CA, 'spin 0, C_1 beta0 G^2': -2,
           'spin 2, K G^2': -4*CA, 'spin 2, K beta0 G': -4}

    print()
    print('Coefficients that do not depend on the scheme, the branch of the logs or mu_R:')
    print(f'  {"":24s} {"finite remainder":>17s} {"UV + Catani add":>16s} {"two-loop amplitude":>19s}')
    print(f'  {"":24s} {"(measured)":>17s} {"":>16s} {"before both, O(eps^0)":>19s}')
    for k in fin:
        bare = S.simplify(fin[k]-added[k])
        print(f'  {k:24s} {str(fin[k]):>17s} {str(added[k]):>16s} {str(bare):>19s}')
        assert S.simplify(added[k]+fin[k]) == 0
    print()
    print('Pieces that do depend on conventions (not claimed; a0, k1 are the O(eps^0), O(eps) terms of the region):')
    print('  spin 0, G^2 without beta0:', S.simplify(g2_rest.subs(Cl, C1/2)))
    print('  spin 2, G   without beta0:', h1_rest)
    print()
    print('In each convention-independent coefficient UV renormalisation plus the Catani subtraction')
    print('contribute exactly minus the measured value, so the two-loop amplitude itself carries twice it.')

    # The table above as data: Table 4 of the paper is built from this file (make_tables.py),
    # so nothing in it is typed by hand. Entries are sympy expressions written as strings.
    import json, pathlib
    rows = [{'coefficient': k, 'finite_remainder': str(fin[k]), 'added_by_uv_and_catani': str(added[k]),
             'two_loop_amplitude': str(S.simplify(fin[k]-added[k]))} for k in fin]
    out = pathlib.Path(__file__).resolve().with_name('results_stage2a.json')
    out.write_text(json.dumps({'rows': rows, 'same_in_both_eps_conventions': True,
                               'sympy': S.__version__}, indent=1)+'\n')
    print(f'wrote {out.name}')
